export function area(input: { width?: number; height?: number }): number {
  const { width, height } = input;
  if (width === undefined || height === undefined) {
    throw new TypeError("width and height are required");   // guard: bad input
  }
  if (width <= 0 || height <= 0) {
    throw new RangeError("width and height must be positive");
  }
  return width * height;   // width/height narrowed to number, path stays flat
}
